import java.util.concurrent.*;

// (1) Callable returns a value; Runnable does not.
Callable<Integer> task = () -> {
    Thread.sleep(1000);
    return 42;                       // returns Integer, can throw checked exc
};

// (2) Submit to an ExecutorService -> get a Future.
ExecutorService pool = Executors.newFixedThreadPool(2);
Future<Integer> future = pool.submit(task);

// (3) Retrieve the result. get() BLOCKS until ready.
while (!future.isDone()) { /* do other work, don't block yet */ }
Integer result = future.get();      // blocks here if not already done
System.out.println(result);         // 42
future.cancel(true);                // cancel a still-running task (interrupt)
pool.shutdown();
```
